    // From SpeedFeatures
    public float maxSpeed() {
        return 200.0f;
    }

    public float maxAcceleration() {
        return 5.5f;
    }

    // From EngineFeatures
    public float numOfCyls() {
        return 6.0f;
    }

    public float enginePower() {
        return 300.0f;
    }
}
```

